// Solid one-cell transition pieces; step 0 is the foot, step 3 the crest.
export const BANK_PROPS=Object.fromEntries(['dirt','grass','sand'].flatMap(surface=>['north','east','south','west'].flatMap(direction=>['left','right'].flatMap(side=>[0,1,2,3].map(step=>['rampbank-'+surface+'-'+direction+'-'+side+'-'+step,{w:1,h:1,solid:true,cover:0}])))));
export const isRampBank=p=>!!BANK_PROPS[p?.kind];
export function bankInfo(p){if(!isRampBank(p))return null;const [_,surface,direction,side,step]=p.kind.split('-');return {surface,direction,side,step:Number(step)};}
export function bankHeight(step,u,v){const t=(step+u)/4,bank=v<.65?.55*Math.pow(v/.65,1.7):.55+.45*Math.min(1,(v-.65)/.18);return 2*(t+(1-t)*bank);}
export function bankTriangles(step,side){const triangles=[],n=12,point=(u,v)=>[u-.5,bankHeight(step,u,v), (side==='left'?-1:1)*(v-.5)],tri=(a,b,c)=>{if(side==='left')triangles.push(a,c,b);else triangles.push(a,b,c);};
 for(let i=0;i<n;i++)for(let j=0;j<n;j++){const a=point(i/n,j/n),b=point((i+1)/n,j/n),c=point((i+1)/n,(j+1)/n),d=point(i/n,(j+1)/n);tri(a,c,b);tri(a,d,c);}
 for(const edge of [Array.from({length:n+1},(_,i)=>point(i/n,0)),Array.from({length:n+1},(_,i)=>point(1,i/n)),Array.from({length:n+1},(_,i)=>point(1-i/n,1)),Array.from({length:n+1},(_,i)=>point(0,1-i/n))])for(let i=0;i<n;i++){const a=edge[i],b=edge[i+1],c=[b[0],0,b[2]],d=[a[0],0,a[2]];tri(a,b,c);tri(a,c,d);}
 return triangles;
}
export const BANK_YAW={east:0,south:-Math.PI/2,west:Math.PI,north:Math.PI/2};
export function bankSet(ramp,surface='dirt'){if(ramp.kind.startsWith('ramp-wood'))throw Error('Wooden ramps already have timber sides; earth banks only fit four-tile ramps.');const [_,__,direction]=ramp.kind.split('-'),[dx,dy]={east:[1,0],south:[0,1],west:[-1,0],north:[0,-1]}[direction],low={x:ramp.x+(dx<0?3:0),y:ramp.y+(dy<0?3:0)};return ['left','right'].flatMap(side=>[0,1,2,3].map(step=>{const sign=side==='left'?-1:1;return {x:low.x+dx*step-dy*sign,y:low.y+dy*step+dx*sign,z:ramp.z||0,kind:'rampbank-'+surface+'-'+direction+'-'+side+'-'+step};}));}
// The same mesh triangles drive shot/lighting occlusion; no full-height proxy.
const cache=new Map();
export function bankRayHit(props,o,d,limit){let nearest=null;for(const p of props||[]){const b=bankInfo(p);if(!b)continue;let lo=0,hi=limit;for(const [v,dv,min,max]of [[o.x,d.x,p.x-.5,p.x+.5],[o.y,d.y,p.y-.5,p.y+.5],[o.h,d.h,(p.z||0)*3,(p.z||0)*3+2]]){if(Math.abs(dv)<1e-9){if(v<min||v>max){hi=-1;break;}}else{const a=(min-v)/dv,c=(max-v)/dv;lo=Math.max(lo,Math.min(a,c));hi=Math.min(hi,Math.max(a,c));}}if(lo>hi)continue;const yaw=BANK_YAW[b.direction],c=Math.cos(yaw),s=Math.sin(yaw),ox=o.x-p.x,oz=o.y-p.y,origin=[c*ox-s*oz,o.h-(p.z||0)*3,s*ox+c*oz],dir=[c*d.x-s*d.y,d.h,s*d.x+c*d.y],key=b.step+b.side;let ts=cache.get(key);if(!ts){ts=bankTriangles(b.step,b.side);cache.set(key,ts);}for(let i=0;i<ts.length;i+=3){const a=ts[i],e1=ts[i+1].map((v,j)=>v-a[j]),e2=ts[i+2].map((v,j)=>v-a[j]),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],dot=(a,b)=>a.reduce((n,v,j)=>n+v*b[j],0),h=cross(dir,e2),det=dot(e1,h);if(Math.abs(det)<1e-8)continue;const v=origin.map((n,j)=>n-a[j]),u=dot(v,h)/det;if(u<0||u>1)continue;const q=cross(v,e1),w=dot(dir,q)/det;if(w<0||u+w>1)continue;const t=dot(e2,q)/det;if(t>1e-6&&t<=limit&&(nearest===null||t<nearest))nearest=t;}}return nearest;}
